ADA_OPTIONAL_CLASSIFICATIONS = frozenset({
    "BASEADA", "TEADAFL", "ADAINDFL", "ADABSTFL", "ADAPERFL", "ADATRNFL", "NABFL",
})


def _codes(value, default):
    if value is None:
        value = default
    if isinstance(value, str):
        value = value.split(",")
    codes = {str(item).strip().upper() for item in value if str(item).strip()}
    if any(not re.fullmatch(r"[A-Z][A-Z0-9_]*", code) for code in codes):
        raise ValueError("Analysis column names must be canonical identifiers")
    return codes


def required_columns(design, stem, values=None):
    """Return fresh domain-to-required-column sets for a supported R output.

    Dynamic baseline selections are the only required ADSL characteristics;
    unrelated disease or client-specific fields are never implicitly required.
    Population and analysis flags must already be derived in the supplied data.
    """
    try:
        result = {slot: set(columns.split()) for slot, columns in _CONTRACTS[design][stem].items()}
    except KeyError as exc:
        raise ValueError(f"Unsupported runnable analysis: {design}/{stem}") from exc
    if stem == "t_baseline_characteristics":
        values = values or {}
        result["adsl"].update(_codes(values.get("baseline_continuous"), "SBPBL,DBPBL,PULSEBL"))
        result["adsl"].update(_codes(values.get("baseline_categorical"), "SMOKSTAT,ALCOHOL"))
    return result


def optional_columns(design, stem):
    """Classification flags can be mapped without becoming mandatory uploads."""
    required_columns(design, stem)
    return {"adis": set(ADA_OPTIONAL_CLASSIFICATIONS)} if stem == "t_ada_summary" else {}
